CREATE TYPE "Role" AS ENUM ('ADMIN','HR','MANAGER','EMPLOYEE');
CREATE TYPE "EmploymentStatus" AS ENUM ('ACTIVE','ON_LEAVE','INACTIVE');
CREATE TYPE "LeaveStatus" AS ENUM ('PENDING','APPROVED','REJECTED','CANCELLED');
CREATE TABLE "Department" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"costCenter" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "Department_name_key" ON "Department"("name"); CREATE UNIQUE INDEX "Department_costCenter_key" ON "Department"("costCenter");
CREATE TABLE "Employee" ("id" TEXT PRIMARY KEY,"employeeNumber" TEXT NOT NULL,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"role" "Role" NOT NULL DEFAULT 'EMPLOYEE',"jobTitle" TEXT NOT NULL,"status" "EmploymentStatus" NOT NULL DEFAULT 'ACTIVE',"startDate" TIMESTAMP(3) NOT NULL,"leaveAllowance" INTEGER NOT NULL DEFAULT 20,"departmentId" TEXT NOT NULL,"managerId" TEXT,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "Employee_employeeNumber_key" ON "Employee"("employeeNumber"); CREATE UNIQUE INDEX "Employee_email_key" ON "Employee"("email"); CREATE INDEX "Employee_departmentId_idx" ON "Employee"("departmentId"); CREATE INDEX "Employee_managerId_idx" ON "Employee"("managerId"); CREATE INDEX "Employee_status_idx" ON "Employee"("status");
CREATE TABLE "Session" ("id" TEXT PRIMARY KEY,"tokenHash" TEXT NOT NULL,"employeeId" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "Session_tokenHash_key" ON "Session"("tokenHash"); CREATE INDEX "Session_employeeId_idx" ON "Session"("employeeId"); CREATE INDEX "Session_expiresAt_idx" ON "Session"("expiresAt");
CREATE TABLE "LeaveRequest" ("id" TEXT PRIMARY KEY,"employeeId" TEXT NOT NULL,"reviewerId" TEXT,"startDate" TIMESTAMP(3) NOT NULL,"endDate" TIMESTAMP(3) NOT NULL,"days" INTEGER NOT NULL,"reason" TEXT NOT NULL,"status" "LeaveStatus" NOT NULL DEFAULT 'PENDING',"reviewedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "LeaveRequest_employeeId_status_idx" ON "LeaveRequest"("employeeId","status"); CREATE INDEX "LeaveRequest_reviewerId_idx" ON "LeaveRequest"("reviewerId");
CREATE TABLE "Attendance" ("id" TEXT PRIMARY KEY,"employeeId" TEXT NOT NULL,"workDate" DATE NOT NULL,"clockIn" TIMESTAMP(3),"clockOut" TIMESTAMP(3));
CREATE UNIQUE INDEX "Attendance_employeeId_workDate_key" ON "Attendance"("employeeId","workDate"); CREATE INDEX "Attendance_workDate_idx" ON "Attendance"("workDate");
ALTER TABLE "Employee" ADD CONSTRAINT "Employee_departmentId_fkey" FOREIGN KEY ("departmentId") REFERENCES "Department"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Employee" ADD CONSTRAINT "Employee_managerId_fkey" FOREIGN KEY ("managerId") REFERENCES "Employee"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Session" ADD CONSTRAINT "Session_employeeId_fkey" FOREIGN KEY ("employeeId") REFERENCES "Employee"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "LeaveRequest" ADD CONSTRAINT "LeaveRequest_employeeId_fkey" FOREIGN KEY ("employeeId") REFERENCES "Employee"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "LeaveRequest" ADD CONSTRAINT "LeaveRequest_reviewerId_fkey" FOREIGN KEY ("reviewerId") REFERENCES "Employee"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Attendance" ADD CONSTRAINT "Attendance_employeeId_fkey" FOREIGN KEY ("employeeId") REFERENCES "Employee"("id") ON DELETE CASCADE ON UPDATE CASCADE;
